// Rendered side of the fetch-mode benchmark: the same robots-allowed URLs in Chromium.
// node render_side.mjs <out dir>   (reads targets.json written by http_side.py)
// ECDEV user agent, the session proxy with TLS verification on, load event plus 8 s settle (retail pages never reach network idle), 2 s per host.
import { createRequire } from 'module';
import fs from 'fs';
const require = createRequire('/opt/node-tools/');
const { chromium } = require('playwright');
const out = process.argv[2];
const targets = JSON.parse(fs.readFileSync(`${out}/targets.json`));
const browser = await chromium.launch({ executablePath: '/opt/pw-browsers/chromium-1194/chrome-linux/chrome', proxy: { server: process.env.https_proxy } });
const context = await browser.newContext({ userAgent: 'ECDEV/0.1 (+read-only research)' });
const last = {};
for (const t of targets) {
  if (!t.robots?.allowed) continue;
  const host = new URL(t.url).host;
  const wait = 2000 - (Date.now() - (last[host] ?? 0));
  if (wait > 0) await new Promise(r => setTimeout(r, wait));
  const page = await context.newPage();
  const started = Date.now();
  try {
    const resp = await page.goto(t.url, { waitUntil: 'load', timeout: 60000 });
    await page.waitForTimeout(8000);
    const html = await page.content();
    fs.writeFileSync(`${out}/render-${String(t.id).padStart(3, '0')}.html`, html);
    t.render = { status: resp?.status() ?? null, final_url: page.url(), bytes: Buffer.byteLength(html), ms: Date.now() - started, file: `render-${String(t.id).padStart(3, '0')}.html` };
  } catch (e) { t.render = { status: 'ERROR', error: String(e).slice(0, 200) }; }
  last[host] = Date.now();
  await page.close();
}
await browser.close();
fs.writeFileSync(`${out}/targets.json`, JSON.stringify(targets, null, 1));
console.log(targets.filter(t => t.render?.status === 200).length, 'rendered');

