//! ECDEV side of the fetch-mode benchmark, using ECDEV's own code paths.
//!   robots <robots.txt file or -> <url>   -> prints {"allowed":bool,"crawl_delay":f64|null}
//!   extract <html file> <content-type> <url> -> prints the products ECDEV extracts
use serde_json::{Value, json};
fn main() {
    let a: Vec<String> = std::env::args().collect();
    match a[1].as_str() {
        "robots" => {
            let text = if a[2] == "-" { String::new() } else { std::fs::read_to_string(&a[2]).unwrap() };
            let d = ecdev_web::robots::evaluate(&text, &a[3], "ECDEV");
            println!("{}", json!({"allowed": d.allowed, "crawl_delay": d.crawl_delay_seconds, "evidence": d.evidence}));
        }
        "extract" => {
            let bytes = std::fs::read(&a[2]).unwrap();
            let out = match ecdev_web::document::extract(&bytes, &a[3], &a[4]) {
                Ok(v) => {
                    let products: Vec<Value> = v["products"].as_array().into_iter().flatten().map(|p| json!({
                        "title": p["title"], "sku": p["sku"], "price_minor": p["price_minor"], "currency": p["currency"],
                        "availability": p["availability"], "price_source": p["price"]["source"].clone(),
                    })).collect();
                    json!({"ok": true, "products": products, "page_role": v["page_role"]})
                }
                Err(e) => json!({"ok": false, "error": e}),
            };
            println!("{out}");
        }
        _ => panic!("mode"),
    }
}
